# forge_engineimport streamlit as stimport reimport jsonimport osfrom datetime import datetimefrom create_tools.json_modifiers import update_nested_keysdef run_forge_workflow(PATHS, load_json_registry, get_next_available_id):    """Forge Engine: Handles the creation of a complete file logic set."""    st.title("Logic Map Files")    st.header("Forge New Metric Suite")            sections = load_json_registry("ISIC_Industry_Section_Codes.json") or [{"Industry Sector Name": "General", "ISIC Section": "Z"}]    divisions = load_json_registry("ISIC_Industry_Division_Codes.json") or []    pcf_cats = load_json_registry("PCF_Categories.json") or [{"PCF Category": "Generic", "PCF Code": "0.0"}]            col_name, col_id = st.columns([3, 1])    logic_map_name = col_name.text_input("Metric Name (Logic Label)")    unique_id = col_id.text_input("ID", value=str(get_next_available_id(PATHS)))             section = st.selectbox("Industry Section", sections, format_func=lambda x: x.get("Industry Sector Name"))    sec_letter = section.get("ISIC Section", "Z")            filtered_divs = [d for d in divisions if d.get("ISIC Section") == sec_letter] or [{"Industry Sector / Activity Name": "Default", "ISIC Division": "00"}]    division = st.selectbox("Industry Division", filtered_divs, format_func=lambda x: x.get("Industry Sector / Activity Name"))    pcf = st.selectbox("PCF Category", pcf_cats, format_func=lambda x: x.get("PCF Category"))            pcf_code = str(pcf.get('PCF Code')).split('.')[-1].zfill(2)    div_code = re.sub(r'\D', '', str(division.get('ISIC Division')))[-3:].zfill(3)    full_itw_id = f"ITW-{unique_id}.{pcf_code}-{sec_letter}.{div_code}.REF.001"            st.info(f"**Target ITW_ID:** `{full_itw_id}`")        fallbacks = {        "BRG": {"Context": {}, "Kinetic_Link": "", "Source_Event": "", "Target_Action": ""},        "DIC": {"Physical_Mapping": [], "Source_Columns": [], "Target_Fields": []},        "ERD": {"Conceptual_Blueprint": {}, "Entities": [], "Relationships": []},        "LDD": {"Mathematical_Calculations": "", "Validation_Logic": "", "Proof_Source": ""},        "LUT": {"Universal_Translator": {}, "Categorical_Labels": [], "Hierarchies": []},        "MAN": {"Metric_Manifest": {}, "Business_Owner": "Unassigned"},        "SEM": {"Business_Why": "", "Stakeholder_Persona": "", "Intent_Anchors": []}    }        c1, c2, _ = st.columns([3, 3, 2])    if c1.button("Generate Logic Set"):        if not logic_map_name.strip():            st.error("Please enter a Metric Name."); return        generated_files, timestamp = [], datetime.now().strftime("%Y-%m-%d %H:%M:%S")        template_dir = PATHS.get("templates", PATHS["spec"].parent / "templates")                try:            for prefix, default_structure in fallbacks.items():                specific_filename = f"{prefix}_{full_itw_id}.json"                target_path = PATHS["spec"] / specific_filename                content = dict(default_structure)                                if template_dir.exists():                    matched_files = [f for f in os.listdir(template_dir) if f.upper().startswith(prefix)]                    if matched_files:                        try:                            with open(template_dir / matched_files[0], "r", encoding="utf-8") as tf:                                raw_data = json.load(tf)                                content = raw_data if isinstance(raw_data, dict) else {f"{prefix}_data": raw_data}                        except json.JSONDecodeError:                            st.warning(f"⚠️ `{matched_files[0]}` has a syntax error. Using clean fallback structure.")                                # Perform search-and-replace update across nested structures via the imported tool                update_nested_keys(content, {                    "itw_id": specific_filename.replace(".json", ""),                     "metric_name": logic_map_name,                    "version": "001", "last_updated": timestamp                })                                if prefix == "BRG":                    if "Context" not in content or not isinstance(content["Context"], dict):                        content["Context"] = {}                    content["Context"].update({                        "Layer": "Bridge", "Industry": section.get("Industry Sector Name", "General"),                        "Division": division.get("Industry Sector / Activity Name", "Default"),                        "Status": "Draft", "Version": "001",                        "Protocol_Status": "Thought Leadership", "Usage_Notice": "Open-Source Logic Specification Protocol"                    })                                with open(target_path, "w", encoding="utf-8") as f:                    json.dump(content, f, indent=4)                generated_files.append(str(target_path))                        st.session_state.last_generated_set = generated_files            st.session_state.set_created = True            st.success(f"Successfully generated a complete file logic set!"); st.rerun()                    except Exception as e:            st.error(f"Error during execution: {str(e)}")            for path in generated_files:                 if os.path.exists(path): os.remove(path)    if st.session_state.get('set_created', False) and c2.button("Discard/Undo"):        paths_to_remove = st.session_state.get('last_generated_set', [])        removed_count = sum(1 for p in paths_to_remove if os.path.exists(p) and not os.remove(p))        st.session_state.set_created = False        st.session_state.last_generated_set = []        st.warning(f"Discarded and deleted {removed_count} generated files."); st.rerun()